<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import SignalChart from './components/SignalChart.vue';import {exportZip,loadDataset,preview,series} from './api';import type{Activity,Inventory,Norm,Point}from'./types';import{formatDuration,normalizationError}from'./utils';
const path=ref('dataset/cleaned'),maxHours=ref<number|null>(null),inventory=ref<Inventory|null>(null),loading=ref(false),error=ref('');const cache=reactive<Record<string,Point[]>>({});const selected=ref<Activity|null>(null),detail=ref<Point[]>([]),firstLap=ref(1),lastLap=ref(1),previewPoints=ref<Point[]>([]),destination=ref(''),message=ref('');
const norm=reactive<Norm>({weightKg:null,hrMaxBpm:null,hrThresholdBpm:null,normalizePower:false,normalizeHrMax:false,normalizeHrThreshold:false});
const normError=computed(()=>normalizationError(norm.normalizePower,String(norm.weightKg??''),'Peso')||normalizationError(norm.normalizeHrMax,String(norm.hrMaxBpm??''),'FC massima')||normalizationError(norm.normalizeHrThreshold,String(norm.hrThresholdBpm??''),'FC di soglia'));
async function load(){loading.value=true;error.value='';try{inventory.value=await loadDataset(path.value,maxHours.value?maxHours.value*3600:null);for(const a of [...inventory.value.extractable,...inventory.value.excluded])series(a.activityId).then(x=>cache[a.activityId]=x)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function open(a:Activity){selected.value=a;detail.value=cache[a.activityId]||await series(a.activityId);if(a.laps.length){firstLap.value=lastLap.value=a.laps[0].index}}
function extend(i:number){if(i===firstLap.value-1)firstLap.value=i;else if(i===lastLap.value+1)lastLap.value=i;else firstLap.value=lastLap.value=i;previewPoints.value=[]}
async function makePreview(){if(!selected.value||normError.value)return;previewPoints.value=await preview(selected.value.activityId,firstLap.value,lastLap.value,norm)}
async function doExport(){if(!selected.value||normError.value)return;const r=await exportZip(selected.value.activityId,firstLap.value,lastLap.value,norm,destination.value);if(r.headers.get('content-type')?.includes('zip')){const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download='dataset_segments.zip';a.click();URL.revokeObjectURL(u);message.value='ZIP scaricato'}else message.value=`Esportato in ${(await r.json()).writtenPath}`}
</script>
<template><main class="shell"><header><h1>Dataset exploration</h1><p>Potenza, frequenza cardiaca e segmenti lap</p></header>
<section class="controls"><label for="dataset-path">Percorso dataset<input id="dataset-path" v-model="path"></label><label>Durata massima (ore)<input v-model.number="maxHours" type="number" min="0" step="0.5" placeholder="Tutte"></label><button @click="load" :disabled="loading">{{loading?'Caricamento…':'Carica dataset'}}</button></section><p v-if="error" class="error">{{error}}</p>
<template v-if="inventory"><section><h2>Attività estraibili <span>{{inventory.extractable.length}}</span></h2><div class="grid"><article v-for="a in inventory.extractable" :key="a.activityId" class="card" @click="open(a)"><div class="cardhead"><strong>{{a.activityId}}</strong><span>{{formatDuration(a.durationSeconds)}} · {{a.laps.length}} lap</span></div><SignalChart v-if="cache[a.activityId]" :points="cache[a.activityId]" :duration="a.durationSeconds"/><p v-else>Caricamento serie…</p></article></div></section>
<section><h2>Esclusi dall'estrazione <span>{{inventory.excluded.length}}</span></h2><div class="grid"><article v-for="a in inventory.excluded" :key="a.activityId" class="card excluded" @click="open(a)"><div class="cardhead"><strong>{{a.activityId}}</strong><span>{{formatDuration(a.durationSeconds)}}</span></div><SignalChart v-if="cache[a.activityId]" :points="cache[a.activityId]" :duration="a.durationSeconds"/><p class="badge">{{a.exclusionReason}}</p></article></div></section></template>
<div v-if="selected" class="overlay" @click.self="selected=null"><section class="detail"><button class="close" @click="selected=null">Chiudi</button><h2>{{selected.activityId}}</h2><SignalChart :points="previewPoints.length?previewPoints:detail" :laps="selected.laps" :duration="previewPoints.length?(previewPoints.at(-1)?.elapsedSeconds||0):selected.durationSeconds" detail/>
<template v-if="selected.extractable"><h3>Lap da estrarre</h3><div class="laps"><button v-for="l in selected.laps" :key="l.index" :class="{active:l.index>=firstLap&&l.index<=lastLap}" @click="extend(l.index)">Lap {{l.index}}<small>{{formatDuration(l.durationSeconds)}}</small></button></div><div class="normal"><label><input type="checkbox" v-model="norm.normalizePower"> W/kg</label><input v-model.number="norm.weightKg" type="number" placeholder="Peso kg"><label><input type="checkbox" v-model="norm.normalizeHrMax"> % FCmax</label><input v-model.number="norm.hrMaxBpm" type="number" placeholder="FC max bpm"><label><input type="checkbox" v-model="norm.normalizeHrThreshold"> % FC soglia</label><input v-model.number="norm.hrThresholdBpm" type="number" placeholder="FC soglia bpm"></div><p v-if="normError" class="error">{{normError}}</p><div class="actions"><button @click="makePreview">Anteprima segmento</button><input v-model="destination" placeholder="Destinazione ZIP (opzionale)"><button @click="doExport">Esporta lap {{firstLap}}–{{lastLap}}</button></div><p>{{message}}</p></template><p v-else class="badge">{{selected.exclusionReason}}</p></section></div></main></template>
